"use client";

import { useState } from "react";

import {
	Chart as ChartJS,
	CategoryScale,
	LinearScale,
	PointElement,
	LineElement,
	Title,
	Tooltip,
	Legend,
	Filler,
	type ChartOptions,
	type ChartData,
} from "chart.js";

import { Line } from "react-chartjs-2";

// Register Chart.js components
ChartJS.register(
	CategoryScale,
	LinearScale,
	PointElement,
	LineElement,
	Title,
	Tooltip,
	Legend,
	Filler,
);

const labels = [
	"Jan",
	"Feb",
	"Mar",
	"Apr",
	"May",
	"Jun",
	"Jul",
	"Aug",
	"Sep",
	"Oct",
	"Nov",
	"Dec",
];

//* this option generated by GPT
const options: ChartOptions<"line"> = {
	responsive: true,
	maintainAspectRatio: false,

	interaction: {
		mode: "index",
		intersect: false,
	},

	plugins: {
		legend: {
			display: true,
			position: "top",
			align: "center",
		},

		title: {
			display: true,
			text: "Application Activity",
			color: "#f5f5f5",
			align: "start",
			font: {
				size: 18,
				weight: "bold",
			},
		},

		tooltip: {
			enabled: true,
			backgroundColor: "#001220",
			padding: 12,
			cornerRadius: 8,
		},
	},

	scales: {
		x: {
			grid: {
				display: false,
			},
		},

		y: {
			beginAtZero: true,
			grid: {
				color: "rgba(128, 128, 128, 0.15)",
			},
			ticks: {
				precision: 0,
			},
		},
	},
};

interface Props {
	dataProps: {
		Applied: number[];
		InProgress: number[];
		Interview: number[];
		Accepted: number[];
		Rejected: number[];
	};
}

export default function DashboardLineChart({ dataProps }: Props) {
	const [timeframe, setTimeframe] = useState<number>(0);
	const dateOptionClassName = "bg-(--custom-border)";

	//* remove labels array index based on option timeFrame
	const usedLabels =
		timeframe === 12
			? labels
			: timeframe === 0
				? labels.slice(0, dataProps.Applied.length)
				: labels.slice(
						dataProps.Applied.length - timeframe,
						dataProps.Applied.length,
					);
	const handleTimeFrameOption = (e: React.ChangeEvent<HTMLSelectElement>) => {
		setTimeframe(Number(e.target.value));
	};

	//* this data generated by GPT and edited by MRaihanZ
	const data: ChartData<"line"> = {
		labels: usedLabels,
		datasets: [
			{
				label: "Applied",
				data: dataProps.Applied,
				borderColor: "#fbae3c",
				backgroundColor: "rgba(251, 174, 60, 0.15)",
				borderWidth: 3,
				fill: true,
				tension: 0.4,
				pointRadius: 4,
				pointHoverRadius: 7,
				pointBackgroundColor: "#FBAE3C",
				pointBorderColor: "#ffffff",
				pointBorderWidth: 2,
			},
			{
				label: "In Progress",
				data: dataProps.InProgress,
				borderColor: "#42a5f5",
				backgroundColor: "rgba(66, 165, 245, 0.15)",
				borderWidth: 3,
				fill: true,
				tension: 0.4,
				pointRadius: 4,
				pointHoverRadius: 7,
				pointBackgroundColor: "#42a5f5",
				pointBorderColor: "#ffffff",
				pointBorderWidth: 2,
				hidden: true,
			},
			{
				label: "Interview",
				data: dataProps.Interview,
				borderColor: "#35b779",
				backgroundColor: "rgba(53, 183, 121, 0.15)",
				borderWidth: 3,
				fill: true,
				tension: 0.4,
				pointRadius: 4,
				pointHoverRadius: 7,
				pointBackgroundColor: "#35b779",
				pointBorderColor: "#ffffff",
				pointBorderWidth: 2,
				hidden: true,
			},
			{
				label: "Accepted",
				data: dataProps.Accepted,
				borderColor: "#bae721",
				backgroundColor: "rgba(186, 231, 33, 0.15)",
				borderWidth: 3,
				fill: true,
				tension: 0.4,
				pointRadius: 4,
				pointHoverRadius: 7,
				pointBackgroundColor: "#bae721",
				pointBorderColor: "#ffffff",
				pointBorderWidth: 2,
			},
			{
				label: "Rejected",
				data: dataProps.Rejected,
				borderColor: "#ef5350",
				backgroundColor: "rgba(239, 83, 80, 0.15)",
				borderWidth: 3,
				fill: true,
				tension: 0.4,
				pointRadius: 4,
				pointHoverRadius: 7,
				pointBackgroundColor: "#ef5350",
				pointBorderColor: "#ffffff",
				pointBorderWidth: 2,
			},
		],
	};
	return (
		<div className="relative h-full w-full">
			<select
				name="Timeframe"
				id="Timeframe"
				value={timeframe}
				onChange={handleTimeFrameOption}
				className="absolute top-5 right-7 px-3 py-0.5 rounded-lg border border-(--custom-border-glass) text-sm"
			>
				<option value={0} className={dateOptionClassName}>
					Default
				</option>
				<option value={1} className={dateOptionClassName}>
					Last 1 Month
				</option>
				<option value={2} className={dateOptionClassName}>
					Last 2 Month
				</option>
				<option value={3} className={dateOptionClassName}>
					Last 3 Month
				</option>
				<option value={6} className={dateOptionClassName}>
					Last 6 Month
				</option>
				<option value={9} className={dateOptionClassName}>
					Last 9 Month
				</option>
				<option value={12} className={dateOptionClassName}>
					Last 12 Month
				</option>
			</select>
			<Line data={data} options={options} className="px-5 py-3" />
		</div>
	);
}
